test('purges an event from long ago', () => {
  const now = 1000 * DAY_MS
  assert.equal(selectForPurge([{ id: 'a', category: 'app', createdAt: 0 }], now).length, 1)
})

test('default retention: keeps an event exactly 90 days old, purges one millisecond older', () => {
  const now = 1000 * DAY_MS
  const atCutoff = { id: 'a', category: 'app', createdAt: now - 90 * DAY_MS }
  const pastCutoff = { id: 'b', category: 'app', createdAt: now - 90 * DAY_MS - 1 }
  const doomed = selectForPurge([atCutoff, pastCutoff], now).map((e) => e.id)
  assert.deepEqual(doomed, ['b'])
})

test('security events get a 400 day retention period', () => {
  const now = 1000 * DAY_MS
  const kept = { id: 'a', category: 'security', createdAt: now - 100 * DAY_MS }
  const atCutoff = { id: 'b', category: 'security', createdAt: now - 400 * DAY_MS }
  const purged = { id: 'c', category: 'security', createdAt: now - 400 * DAY_MS - 1 }
  const doomed = selectForPurge([kept, atCutoff, purged], now).map((e) => e.id)
  assert.deepEqual(doomed, ['c'])
})

test('legal hold entries are never purged, regardless of age or category', () => {
  const now = 1000 * DAY_MS
  const held = { id: 'a', category: 'app', createdAt: 0, legalHold: true }
  const heldSecurity = { id: 'b', category: 'security', createdAt: 0, legalHold: true }
  assert.deepEqual(selectForPurge([held, heldSecurity], now), [])
})
